# Data-room environmental monitoring: compare sensor readings with the site's alert thresholds.
THRESHOLDS = {
    'temperature_c': (18, 27),   # inside the commonly used ASHRAE recommended range
    'humidity_pct': (40, 60),    # site policy band
}
readings = [
    ('Rack A inlet', {'temperature_c': 24.5, 'humidity_pct': 48, 'water_leak': False, 'smoke': False}),
    ('Rack B inlet', {'temperature_c': 29.1, 'humidity_pct': 44, 'water_leak': False, 'smoke': False}),
    ('UPS room', {'temperature_c': 23.0, 'humidity_pct': 33, 'water_leak': False, 'smoke': False}),
    ('Under-floor sensor', {'temperature_c': 21.0, 'humidity_pct': 52, 'water_leak': True, 'smoke': False}),
]
for location, values in readings:
    alerts = []
    for metric, (low, high) in THRESHOLDS.items():
        if not low <= values[metric] <= high:
            alerts.append(f'{metric} {values[metric]} outside {low}-{high}')
    if values['water_leak']:
        alerts.append('WATER LEAK')
    if values['smoke']:
        alerts.append('SMOKE - evacuate and follow the fire procedure')
    print(f"{location:<19} {'; '.join(alerts) if alerts else 'normal'}")
